      &lt;ActionData&gt;{&quot;Tokens&quot;:[{&quot;value&quot;:&quot;BT&quot;,&quot;name&quot;:&quot;BancaCurenta&quot;},{&quot;value&quot;:&quot;BTRL&quot;,&quot;name&quot;:&quot;CodBicCurent&quot;}],&quot;TokenizeTokenNames&quot;:false,&quot;RecursionCount&quot;:&quot;1&quot;}&lt;/ActionData&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
    &lt;/ActionInfo&gt;
    &lt;ActionInfo&gt;
      &lt;ModuleId&gt;1203&lt;/ModuleId&gt;
      &lt;FieldName&gt;Add&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;2&lt;/OrderIndex&gt;
      &lt;ActionType&gt;ShowError&lt;/ActionType&gt;
      &lt;Description&gt;Valideaza IBAN banca curenta&lt;/Description&gt;
      &lt;ActionData&gt;{&quot;Message&quot;:&quot;IBAN-ul introdus nu este valid pentru banca [BancaCurenta]. Codul BIC al bancii&amp;amp;nbsp;[BancaCurenta]&amp;amp;nbsp;din IBAN trebuie sa fie [CodBicCurent].&amp;lt;p&amp;gt;&amp;lt;br&amp;gt;&amp;lt;/p&amp;gt;&quot;}&lt;/ActionData&gt;
      &lt;Condition&gt;string.IsNullOrWhiteSpace(&quot;[p_ContIBAN]&quot;) || &quot;[p_ContIBAN]&quot;.Replace(&quot; &quot;, &quot;&quot;).Length &amp;lt; 8 || &quot;[p_ContIBAN]&quot;.Replace(&quot; &quot;, &quot;&quot;).ToUpper().Substring(4, 4) != &quot;[CodBicCurent]&quot;&lt;/Condition&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
