    &lt;ActionInfo&gt;
      &lt;ModuleId&gt;1203&lt;/ModuleId&gt;
      &lt;FieldName&gt;Add&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;3&lt;/OrderIndex&gt;
      &lt;ActionType&gt;RunSql&lt;/ActionType&gt;
      &lt;Description&gt;Verifica banca existenta la salvare&lt;/Description&gt;
      &lt;ActionData&gt;{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;UseTransactions&quot;:true,&quot;SqlQuery&quot;:&quot;DECLARE @StatusDraft INT;\nDECLARE @BancaExistenta NVARCHAR(20) = N&#39;&#39;;\nDECLARE @SumeBlocate BIT = 0;\n\nSELECT TOP (1)\n    @StatusDraft = Id\nFROM app.StatusCalcul\nWHERE UPPER(LTRIM(RTRIM(Denumire))) = &#39;DRAFT&#39;\nORDER BY Id;\n\nSELECT TOP (1)\n    @BancaExistenta = Banca\nFROM\n(\n    SELECT &#39;BCR&#39; AS Banca\n    FROM app.CardBCR\n    WHERE CNP = @CNP\n      AND CodSucursala = @CodSucursala\n      AND ISNULL(Valid, 1) = 1\n\n    UNION ALL\n\n    SELECT &#39;BRD&#39;\n    FROM app.CardBRD\n    WHERE CNP = @CNP\n      AND CodSucursala = @CodSucursala\n      AND ISNULL(Valid, 1) = 1\n\n    UNION ALL\n\n    SELECT &#39;BT&#39;\n    FROM app.CardBT\n    WHERE CNP = @CNP\n      AND CodSucursala = @CodSucursala\n      AND ISNULL(Valid, 1) = 1\n\n    UNION ALL\n\n    SELECT &#39;CEC&#39;\n    FROM app.CardCEC\n    WHERE CNP = @CNP\n      AND CodSucursala = @CodSucursala\n      AND ISNULL(Valid, 1) = 1\n\n    UNION ALL\n\n    SELECT &#39;ING&#39;\n    FROM app.CardING\n    WHERE CNP = @CNP\n      AND CodSucursala = @CodSucursala\n      AND ISNULL(Valid, 1) = 1\n\n    UNION ALL\n\n    SELECT &#39;EXM&#39;\n    FROM app.CardEXM\n    WHERE CNP = @CNP\n      AND CodSucursala = @CodSucursala\n      AND ISNULL(Valid, 1) = 1\n\n    UNION ALL\n\n    SELECT &#39;RZB&#39;\n    FROM app.CardRZB\n    WHERE CNP = @CNP\n      AND CodSucursala = @CodSucursala\n      AND ISNULL(Valid, 1) = 1\n\n    UNION ALL\n\n    SELECT &#39;UNI&#39;\n    FROM app.CardUNI\n    WHERE CNP = @CNP\n      AND CodSucursala = @CodSucursala\n      AND ISNULL(Valid, 1) = 1\n\n    UNION ALL\n\n    SELECT &#39;ALTE&#39;\n    FROM app.CardALTE\n    WHERE CNP = @CNP\n      AND CodSucursala = @CodSucursala\n      AND ISNULL(Valid, 1) = 1\n) x\nORDER BY\n    CASE WHEN Banca = @BancaCurenta THEN 0 ELSE 1 END,\n    Banca;\n\nIF @StatusDraft IS NULL\nBEGIN\n    SET @SumeBlocate = 1;\nEND\nELSE IF EXISTS\n(\n    SELECT 1\n    FROM\n    (\n        SELECT Marca, CodSucursala, Anul, Luna, Status\n        FROM app.SumaBCR\n\n        UNION ALL\n\n        SELECT Marca, CodSucursala, Anul, Luna, Status\n        FROM app.SumaBRD\n\n        UNION ALL\n\n        SELECT Marca, CodSucursala, Anul, Luna, Status\n        FROM app.SumaBT\n\n        UNION ALL\n\n        SELECT Marca, CodSucursala, Anul, Luna, Status\n        FROM app.SumaCEC\n\n        UNION ALL\n\n        SELECT Marca, CodSucursala, Anul, Luna, Status\n        FROM app.SumaING\n\n        UNION ALL\n\n        SELECT Marca, CodSucursala, Anul, Luna, Status\n        FROM app.SumaEXM\n\n        UNION ALL\n\n        SELECT Marca, CodSucursala, Anul, Luna, Status\n        FROM app.SumaRZB\n\n        UNION ALL\n\n        SELECT Marca, CodSucursala, Anul, Luna, Status\n        FROM app.SumaUNI\n\n        UNION ALL\n\n        SELECT Marca, CodSucursala, Anul, Luna, Status\n        FROM app.SumaALTE\n    ) sx\n    WHERE LTRIM(RTRIM(sx.Marca)) = LTRIM(RTRIM(@Marca))\n      AND sx.CodSucursala = @CodSucursala\n      AND sx.Anul = @Anul\n      AND sx.Luna = @Luna\n      AND ISNULL(sx.Status, -1) &amp;lt;&amp;gt; @StatusDraft\n)\nBEGIN\n    SET @SumeBlocate = 1;\nEND;\n\nSELECT\n    ISNULL(@BancaExistenta, N&#39;&#39;) AS Banca,\n    @SumeBlocate AS SumeBlocate,\n\n    CASE\n        WHEN @StatusDraft IS NULL\n            THEN N&#39;Nu a fost identificat statusul Draft in app.StatusCalcul.&#39;\n\n        WHEN @SumeBlocate = 1\n            THEN N&#39;Cardul nu poate fi adaugat sau mutat deoarece exista sume confirmate sau aflate in fluxul de plata.&#39;\n\n        WHEN ISNULL(@BancaExistenta, N&#39;&#39;) &amp;lt;&amp;gt; N&#39;&#39;\n         AND @BancaExistenta &amp;lt;&amp;gt; @BancaCurenta\n            THEN N&#39;Acest salariat are deja un card &#39;\n               + @BancaExistenta\n               + N&#39; inregistrat. Pentru adaugarea unui card &#39;\n               + @BancaCurenta\n               + N&#39; si invalidarea cardului vechi, bifati casuta pentru confirmare.&#39;\n\n        ELSE N&#39;&#39;\n    END AS Mesaj;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[p_CNP]&quot;,&quot;name&quot;:&quot;CNP&quot;},{&quot;value&quot;:&quot;[p_Marca]&quot;,&quot;name&quot;:&quot;Marca&quot;},{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;},{&quot;value&quot;:&quot;[BancaCurenta]&quot;,&quot;name&quot;:&quot;BancaCurenta&quot;}],&quot;OutputTokenName&quot;:&quot;CardExistentAdd&quot;,&quot;ExtractColumns&quot;:null,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false}&lt;/ActionData&gt;
      &lt;Condition&gt;[p_CNP] != &quot;&quot;&lt;/Condition&gt;
