      &lt;Condition&gt;&quot;[CardExistentAdd:SumeBlocate]&quot; == &quot;True&quot; || ( !string.IsNullOrWhiteSpace(&quot;[CardExistentAdd:Banca]&quot;) &amp;amp;&amp;amp; &quot;[CardExistentAdd:Banca]&quot; != &quot;[BancaCurenta]&quot; &amp;amp;&amp;amp; &quot;[ConfirmaMutareCard]&quot; != &quot;True&quot; )&lt;/Condition&gt;
