      &lt;ActionData&gt;{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;UseTransactions&quot;:true,&quot;SqlQuery&quot;:&quot;UPDATE app.CardBCR\nSET Valid = 0\nWHERE @BancaCurenta &amp;lt;&amp;gt; &#39;BCR&#39;\n  AND CNP = @CNP\n  AND CodSucursala = @CodSucursala\n  AND ISNULL(Valid, 1) = 1;\n\nUPDATE app.CardBRD\nSET Valid = 0\nWHERE @BancaCurenta &amp;lt;&amp;gt; &#39;BRD&#39;\n  AND CNP = @CNP\n  AND CodSucursala = @CodSucursala\n  AND ISNULL(Valid, 1) = 1;\n\nUPDATE app.CardBT\nSET Valid = 0\nWHERE @BancaCurenta &amp;lt;&amp;gt; &#39;BT&#39;\n  AND CNP = @CNP\n  AND CodSucursala = @CodSucursala\n  AND ISNULL(Valid, 1) = 1;\n\nUPDATE app.CardCEC\nSET Valid = 0\nWHERE @BancaCurenta &amp;lt;&amp;gt; &#39;CEC&#39;\n  AND CNP = @CNP\n  AND CodSucursala = @CodSucursala\n  AND ISNULL(Valid, 1) = 1;\n\nUPDATE app.CardING\nSET Valid = 0\nWHERE @BancaCurenta &amp;lt;&amp;gt; &#39;ING&#39;\n  AND CNP = @CNP\n  AND CodSucursala = @CodSucursala\n  AND ISNULL(Valid, 1) = 1;\n\nUPDATE app.CardEXM\nSET Valid = 0\nWHERE @BancaCurenta &amp;lt;&amp;gt; &#39;EXM&#39;\n  AND CNP = @CNP\n  AND CodSucursala = @CodSucursala\n  AND ISNULL(Valid, 1) = 1;\n\nUPDATE app.CardRZB\nSET Valid = 0\nWHERE @BancaCurenta &amp;lt;&amp;gt; &#39;RZB&#39;\n  AND CNP = @CNP\n  AND CodSucursala = @CodSucursala\n  AND ISNULL(Valid, 1) = 1;\n\nUPDATE app.CardUNI\nSET Valid = 0\nWHERE @BancaCurenta &amp;lt;&amp;gt; &#39;UNI&#39;\n  AND CNP = @CNP\n  AND CodSucursala = @CodSucursala\n  AND ISNULL(Valid, 1) = 1;\n\nUPDATE app.CardALTE\nSET Valid = 0\nWHERE @BancaCurenta &amp;lt;&amp;gt; &#39;ALTE&#39;\n  AND CNP = @CNP\n  AND CodSucursala = @CodSucursala\n  AND ISNULL(Valid, 1) = 1;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[p_CNP]&quot;,&quot;name&quot;:&quot;CNP&quot;},{&quot;value&quot;:&quot;[p_CodSucursala]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[BancaCurenta]&quot;,&quot;name&quot;:&quot;BancaCurenta&quot;}],&quot;OutputTokenName&quot;:null,&quot;ExtractColumns&quot;:null,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false}&lt;/ActionData&gt;
      &lt;Condition&gt;!string.IsNullOrWhiteSpace(&quot;[CardExistentAdd:Banca]&quot;) &amp;amp;&amp;amp; &quot;[CardExistentAdd:Banca]&quot; != &quot;[BancaCurenta]&quot; &amp;amp;&amp;amp; &quot;[ConfirmaMutareCard]&quot; == &quot;True&quot;&lt;/Condition&gt;
