      &lt;Description&gt;Blocheaza modificarea cardului cu sume in flux&lt;/Description&gt;
      &lt;ActionData&gt;{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;UseTransactions&quot;:true,&quot;SqlQuery&quot;:&quot;DECLARE @StatusDraft INT;\nDECLARE @Marca NVARCHAR(100);\nDECLARE @CodSucursalaCard NVARCHAR(50);\n\nSELECT TOP (1)\n    @StatusDraft = Id\nFROM app.StatusCalcul\nWHERE UPPER(LTRIM(RTRIM(Denumire))) = &#39;DRAFT&#39;\nORDER BY Id;\n\nIF @StatusDraft IS NULL\nBEGIN\n    RAISERROR(\n        N&#39;Nu a fost identificat statusul Draft in app.StatusCalcul.&#39;,\n        16,\n        1\n    );\n    RETURN;\nEND;\n\nSELECT\n    @Marca = LTRIM(RTRIM(c.Marca)),\n    @CodSucursalaCard = c.CodSucursala\nFROM app.CardBT c\nWHERE c.Id = @CardId\n  AND c.CodSucursala = @CodSucursala;\n\nIF @Marca IS NULL\nBEGIN\n    RAISERROR(\n        N&#39;Cardul BT selectat nu a fost gasit in sucursala curenta.&#39;,\n        16,\n        1\n    );\n    RETURN;\nEND;\n\nIF EXISTS\n(\n    SELECT 1\n    FROM\n    (\n        SELECT Marca, CodSucursala, Anul, Luna, Status\n        FROM app.SumaBCR\n\n        UNION ALL\n\n        SELECT Marca, CodSucursala, Anul, Luna, Status\n        FROM app.SumaBRD\n\n        UNION ALL\n\n        SELECT Marca, CodSucursala, Anul, Luna, Status\n        FROM app.SumaBT\n\n        UNION ALL\n\n        SELECT Marca, CodSucursala, Anul, Luna, Status\n        FROM app.SumaCEC\n\n        UNION ALL\n\n        SELECT Marca, CodSucursala, Anul, Luna, Status\n        FROM app.SumaING\n\n        UNION ALL\n\n        SELECT Marca, CodSucursala, Anul, Luna, Status\n        FROM app.SumaEXM\n\n        UNION ALL\n\n        SELECT Marca, CodSucursala, Anul, Luna, Status\n        FROM app.SumaRZB\n\n        UNION ALL\n\n        SELECT Marca, CodSucursala, Anul, Luna, Status\n        FROM app.SumaUNI\n\n        UNION ALL\n\n        SELECT Marca, CodSucursala, Anul, Luna, Status\n        FROM app.SumaALTE\n    ) sx\n    WHERE LTRIM(RTRIM(sx.Marca)) = @Marca\n      AND sx.CodSucursala = @CodSucursalaCard\n      AND sx.Anul = @Anul\n      AND sx.Luna = @Luna\n      AND ISNULL(sx.Status, -1) &amp;lt;&amp;gt; @StatusDraft\n)\nBEGIN\n    RAISERROR(\n        N&#39;Cardul nu poate fi modificat deoarece exista sume confirmate sau aflate in fluxul de plata.&#39;,\n        16,\n        1\n    );\n    RETURN;\nEND;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[QueryString:CardBTId=]&quot;,&quot;name&quot;:&quot;CardId&quot;},{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;OutputTokenName&quot;:null,&quot;ExtractColumns&quot;:null,&quot;OnError&quot;:[{&quot;Id&quot;:9073,&quot;GlobalId&quot;:&quot;00000000-0000-0000-0000-000000000000&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:12252,&quot;ActionType&quot;:&quot;ShowError&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;Message&quot;:&quot;&amp;lt;p&amp;gt;Cardul nu poate fi modificat deoarece există sume confirmate sau aflate &#238;n fluxul de plată.&amp;lt;br&amp;gt;&amp;lt;/p&amp;gt;&quot;},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}],&quot;ShowErrors&quot;:false}&lt;/ActionData&gt;
